using Microsoft.EntityFrameworkCore;
using Shameen.Api.Models;

namespace Shameen.Api.Data;
public sealed class TransferDbContext(DbContextOptions<TransferDbContext> options) : DbContext(options) {
    public DbSet<Branch> Branches => Set<Branch>(); public DbSet<DestinationCity> DestinationCities => Set<DestinationCity>(); public DbSet<Employee> Employees => Set<Employee>(); public DbSet<Transfer> Transactions => Set<Transfer>(); public DbSet<OperatingDay> OperatingDays => Set<OperatingDay>(); public DbSet<OperatingDayCurrencyFloat> OperatingDayCurrencyFloats => Set<OperatingDayCurrencyFloat>(); public DbSet<EmployeeCurrencyFloat> EmployeeCurrencyFloats => Set<EmployeeCurrencyFloat>(); public DbSet<CurrencyRate> CurrencyRates => Set<CurrencyRate>(); public DbSet<FloatAdjustment> FloatAdjustments => Set<FloatAdjustment>(); public DbSet<AuthSession> AuthSessions => Set<AuthSession>(); public DbSet<CustomerAccount> CustomerAccounts => Set<CustomerAccount>(); public DbSet<CustomerSession> CustomerSessions => Set<CustomerSession>(); public DbSet<CustomerWalletEntry> CustomerWalletEntries => Set<CustomerWalletEntry>(); public DbSet<CustomerTransferRequest> CustomerTransferRequests => Set<CustomerTransferRequest>();
    protected override void OnModelCreating(ModelBuilder model) {
        model.Entity<DestinationCity>().HasIndex(c => new { c.Country, c.City }).IsUnique(); model.Entity<DestinationCity>().Property(c => c.Country).HasMaxLength(80); model.Entity<DestinationCity>().Property(c => c.City).HasMaxLength(100);
        model.Entity<CustomerAccount>().HasIndex(c => c.Email).IsUnique(); model.Entity<CustomerAccount>().Property(c => c.Name).HasMaxLength(160); model.Entity<CustomerAccount>().Property(c => c.Email).HasMaxLength(320); model.Entity<CustomerAccount>().Property(c => c.PasswordHash).HasMaxLength(512);
        model.Entity<CustomerSession>().HasIndex(s => s.TokenHash).IsUnique(); model.Entity<CustomerSession>().HasIndex(s => new { s.CustomerAccountId, s.ExpiresAtUtc }); model.Entity<CustomerSession>().HasOne(s => s.Customer).WithMany().HasForeignKey(s => s.CustomerAccountId).OnDelete(DeleteBehavior.Cascade);
        model.Entity<CustomerWalletEntry>().HasIndex(e => e.Reference).IsUnique(); model.Entity<CustomerWalletEntry>().HasIndex(e => new { e.CustomerAccountId, e.CurrencyCode, e.Status }); model.Entity<CustomerWalletEntry>().Property(e => e.Kind).HasMaxLength(24); model.Entity<CustomerWalletEntry>().Property(e => e.Status).HasMaxLength(24); model.Entity<CustomerWalletEntry>().Property(e => e.CurrencyCode).HasMaxLength(3); model.Entity<CustomerWalletEntry>().Property(e => e.Amount).HasPrecision(18,2); model.Entity<CustomerWalletEntry>().Property(e => e.Reference).HasMaxLength(32); model.Entity<CustomerWalletEntry>().Property(e => e.PaymentReference).HasMaxLength(120); model.Entity<CustomerWalletEntry>().HasOne(e => e.Customer).WithMany().HasForeignKey(e => e.CustomerAccountId).OnDelete(DeleteBehavior.Restrict);
        model.Entity<CustomerTransferRequest>().HasIndex(r => r.Reference).IsUnique(); model.Entity<CustomerTransferRequest>().HasIndex(r => new { r.CustomerAccountId, r.CreatedAtUtc }); model.Entity<CustomerTransferRequest>().Property(r => r.Reference).HasMaxLength(32); model.Entity<CustomerTransferRequest>().Property(r => r.RecipientName).HasMaxLength(160); model.Entity<CustomerTransferRequest>().Property(r => r.DestinationCountry).HasMaxLength(80); model.Entity<CustomerTransferRequest>().Property(r => r.DestinationCity).HasMaxLength(100); model.Entity<CustomerTransferRequest>().Property(r => r.SourceCurrency).HasMaxLength(3); model.Entity<CustomerTransferRequest>().Property(r => r.PayoutCurrency).HasMaxLength(3); model.Entity<CustomerTransferRequest>().Property(r => r.PayoutMethod).HasMaxLength(40); model.Entity<CustomerTransferRequest>().Property(r => r.Status).HasMaxLength(32); model.Entity<CustomerTransferRequest>().Property(r => r.CollectionReference).HasMaxLength(120); model.Entity<CustomerTransferRequest>().Property(r => r.Amount).HasPrecision(18,2); model.Entity<CustomerTransferRequest>().Property(r => r.PayoutAmount).HasPrecision(18,2); model.Entity<CustomerTransferRequest>().Property(r => r.ExchangeRate).HasPrecision(18,8); model.Entity<CustomerTransferRequest>().HasOne(r => r.Customer).WithMany().HasForeignKey(r => r.CustomerAccountId).OnDelete(DeleteBehavior.Restrict);
        model.Entity<Branch>().HasIndex(b => b.Name).IsUnique(); model.Entity<Branch>().Property(b => b.Name).HasMaxLength(80); model.Entity<Branch>().Property(b => b.City).HasMaxLength(80); model.Entity<Branch>().Property(b => b.Country).HasMaxLength(80).HasDefaultValue("");
        model.Entity<Employee>().HasIndex(e => e.Email).IsUnique(); model.Entity<Employee>().HasIndex(e => e.BranchId); model.Entity<Employee>().Property(e => e.Email).HasMaxLength(320); model.Entity<Employee>().Property(e => e.PasswordHash).HasMaxLength(512); model.Entity<Employee>().Property(e => e.CollectionCountry).HasMaxLength(80); model.Entity<Employee>().Property(e => e.FloatBalance).HasPrecision(18,2); model.Entity<Employee>().Property(e => e.FloatAssigned).HasPrecision(18,2); model.Entity<Employee>().HasOne(e => e.Branch).WithMany().HasForeignKey(e => e.BranchId).OnDelete(DeleteBehavior.Restrict);
        model.Entity<Transfer>().HasIndex(t => t.Reference).IsUnique(); model.Entity<Transfer>().HasIndex(t => new { t.BranchId, t.CreatedAtUtc }); model.Entity<Transfer>().Property(t => t.Amount).HasPrecision(18,2); model.Entity<Transfer>().Property(t => t.PayoutAmount).HasPrecision(18,2); model.Entity<Transfer>().Property(t => t.ExchangeRate).HasPrecision(18,8); model.Entity<Transfer>().Property(t => t.SourceUnitsPerUsd).HasPrecision(18,8); model.Entity<Transfer>().Property(t => t.PayoutUnitsPerUsd).HasPrecision(18,8); model.Entity<Transfer>().Property(t => t.SourceCurrency).HasMaxLength(3).HasDefaultValue("USD"); model.Entity<Transfer>().Property(t => t.PayoutCurrency).HasMaxLength(3).HasDefaultValue("USD"); model.Entity<Transfer>().Property(t => t.Reference).HasMaxLength(32); model.Entity<Transfer>().Property(t => t.Status).HasMaxLength(32); model.Entity<Transfer>().Property(t => t.DestinationCity).HasMaxLength(100); model.Entity<Transfer>().Property(t => t.CollectionReference).HasMaxLength(120); model.Entity<Transfer>().HasOne(t => t.Employee).WithMany(e => e.Transfers).HasForeignKey(t => t.EmployeeId).OnDelete(DeleteBehavior.Restrict); model.Entity<Transfer>().HasOne(t => t.Branch).WithMany().HasForeignKey(t => t.BranchId).OnDelete(DeleteBehavior.Restrict);
        model.Entity<OperatingDay>().HasIndex(d => new { d.Date, d.BranchId }).IsUnique(); model.Entity<OperatingDay>().Property(d => d.OpeningFloat).HasPrecision(18,2); model.Entity<OperatingDay>().Property(d => d.ClosingFloat).HasPrecision(18,2); model.Entity<OperatingDay>().HasOne(d => d.Branch).WithMany().HasForeignKey(d => d.BranchId).OnDelete(DeleteBehavior.Restrict);
        model.Entity<OperatingDayCurrencyFloat>().HasIndex(f => new { f.OperatingDayId, f.CurrencyCode }).IsUnique(); model.Entity<OperatingDayCurrencyFloat>().Property(f => f.CurrencyCode).HasMaxLength(3); model.Entity<OperatingDayCurrencyFloat>().Property(f => f.OpeningFloat).HasPrecision(18,2); model.Entity<OperatingDayCurrencyFloat>().Property(f => f.BranchBalance).HasPrecision(18,2); model.Entity<OperatingDayCurrencyFloat>().Property(f => f.ClosingFloat).HasPrecision(18,2); model.Entity<OperatingDayCurrencyFloat>().HasOne<OperatingDay>().WithMany().HasForeignKey(f => f.OperatingDayId).OnDelete(DeleteBehavior.Cascade);
        model.Entity<EmployeeCurrencyFloat>().HasIndex(f => new { f.OperatingDayId, f.EmployeeId, f.CurrencyCode }).IsUnique(); model.Entity<EmployeeCurrencyFloat>().Property(f => f.CurrencyCode).HasMaxLength(3); model.Entity<EmployeeCurrencyFloat>().Property(f => f.FloatAssigned).HasPrecision(18,2); model.Entity<EmployeeCurrencyFloat>().Property(f => f.FloatBalance).HasPrecision(18,2); model.Entity<EmployeeCurrencyFloat>().HasOne<OperatingDay>().WithMany().HasForeignKey(f => f.OperatingDayId).OnDelete(DeleteBehavior.Restrict); model.Entity<EmployeeCurrencyFloat>().HasOne<Employee>().WithMany().HasForeignKey(f => f.EmployeeId).OnDelete(DeleteBehavior.Restrict);
        model.Entity<CurrencyRate>().HasKey(r => r.CurrencyCode); model.Entity<CurrencyRate>().Property(r => r.CurrencyCode).HasMaxLength(3); model.Entity<CurrencyRate>().Property(r => r.Name).HasMaxLength(80); model.Entity<CurrencyRate>().Property(r => r.UnitsPerUsd).HasPrecision(18,8);
        model.Entity<FloatAdjustment>().HasIndex(a => new { a.OperatingDayId, a.EmployeeId, a.CreatedAtUtc }); model.Entity<FloatAdjustment>().Property(a => a.PreviousAmount).HasPrecision(18,2); model.Entity<FloatAdjustment>().Property(a => a.NewAmount).HasPrecision(18,2); model.Entity<FloatAdjustment>().Property(a => a.CurrencyCode).HasMaxLength(3).HasDefaultValue("USD"); model.Entity<FloatAdjustment>().Property(a => a.Reason).HasMaxLength(500); model.Entity<FloatAdjustment>().HasOne<OperatingDay>().WithMany().HasForeignKey(a => a.OperatingDayId).OnDelete(DeleteBehavior.Restrict); model.Entity<FloatAdjustment>().HasOne<Employee>().WithMany().HasForeignKey(a => a.EmployeeId).OnDelete(DeleteBehavior.Restrict); model.Entity<FloatAdjustment>().HasOne<Employee>().WithMany().HasForeignKey(a => a.ActorEmployeeId).OnDelete(DeleteBehavior.Restrict);
        model.Entity<AuthSession>().HasIndex(s => s.TokenHash).IsUnique(); model.Entity<AuthSession>().Property(s => s.TokenHash).HasMaxLength(64); model.Entity<AuthSession>().HasIndex(s => new { s.EmployeeId, s.ExpiresAtUtc }); model.Entity<AuthSession>().HasOne(s => s.Employee).WithMany().HasForeignKey(s => s.EmployeeId).OnDelete(DeleteBehavior.Cascade);
    }
}
